<section class="mapr-support"><h2>Het juiste onderdeel voor jouw apparaat</h2><p><?php echo esc_html(sprintf('Controleer voor het bestellen altijd het volledige typenummer van je %s %s. Bij sommige onderdelen is ook het product- of servicenummer nodig om de juiste uitvoering te bepalen.',$view->model['brand'],$view->model['commercial_type'])); ?></p><?php if($view->article_links): ?><ul><?php foreach(array_slice($view->article_links,0,2) as $link): if(empty($link['url'])||empty($link['label']))continue; ?><li><a href="<?php echo esc_url($link['url']); ?>"><?php echo esc_html($link['label']); ?></a></li><?php endforeach; ?></ul><?php endif; ?></section>
